import random
import time


def retry(fn, attempts=5, base=0.5, cap=30.0, exceptions=(Exception,)):
    """Call fn(); on failure sleep base * 2**n (jittered, capped) and retry."""
    for n in range(attempts):
        try:
            return fn()
        except exceptions:
            if n == attempts - 1:
                raise
            time.sleep(random.uniform(0, min(cap, base * 2 ** n)))


if __name__ == "__main__":
    calls = []

    def flaky():
        calls.append(1)
        if len(calls) < 3:
            raise ValueError("nope")
        return "ok"

    assert retry(flaky, base=0.001) == "ok" and len(calls) == 3
    try:
        retry(lambda: 1 / 0, attempts=2, base=0.001)
        raise AssertionError("should have raised")
    except ZeroDivisionError:
        pass
```

